import{_ as a,o as s,c as n,a3 as t}from"./chunks/framework.DH50UWNB.js";const k=JSON.parse('{"title":"OpenSpec","description":"","frontmatter":{},"headers":[],"relativePath":"agents/openspec.md","filePath":"agents/openspec.md"}'),o={name:"agents/openspec.md"};function i(p,e,c,d,h,r){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="openspec" tabindex="-1">OpenSpec <a class="header-anchor" href="#openspec" aria-label="Permalink to &quot;OpenSpec&quot;">​</a></h1><p><a href="https://github.com/Fission-AI/OpenSpec" target="_blank" rel="noreferrer">OpenSpec</a> is Wake&#39;s default planning method: each piece of work is a change under <code>openspec/changes/</code>, with a <code>tasks.md</code> that lists its tasks.</p><h2 id="start" tabindex="-1">Start <a class="header-anchor" href="#start" aria-label="Permalink to &quot;Start&quot;">​</a></h2><p>Install OpenSpec as <a href="https://github.com/Fission-AI/OpenSpec" target="_blank" rel="noreferrer">its README</a> explains and run <code>openspec init</code> in the repository. <code>wake init</code> then finds <code>openspec/</code> and records OpenSpec as the plan. When the repository also has Spec Kit or ODD, OpenSpec wins; <code>wake init --plan &lt;method&gt;</code> chooses another.</p><h2 id="planning-with-your-agent" tabindex="-1">Planning with your agent <a class="header-anchor" href="#planning-with-your-agent" aria-label="Permalink to &quot;Planning with your agent&quot;">​</a></h2><p>Ask your agent for a new feature, or run its plan command (such as <code>/wake:plan &lt;idea&gt;</code> in Claude Code). Its <code>wake-planning</code> skill plans the work as a new change with <code>/opsx:propose</code> (<code>/opsx-propose</code> in OpenCode and Pi, <code>$openspec-propose</code> in Codex) and lists it in the <a href="/wake-dist/docs/agents/milestones">milestones file</a>. You review the change and the agent syncs it once you accept; <code>wake watch</code> also syncs on every change under <code>openspec/</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>openspec/</span></span>
<span class="line"><span>  changes/</span></span>
<span class="line"><span>    add-sign-up/</span></span>
<span class="line"><span>      proposal.md</span></span>
<span class="line"><span>      tasks.md          # - [ ] 1.1 Add the sign-up form</span></span>
<span class="line"><span>    archive/</span></span>
<span class="line"><span>      2026-10-17-repo-sync/</span></span>
<span class="line"><span>        tasks.md</span></span>
<span class="line"><span>  milestones.yaml       # optional; see Milestones and task text</span></span></code></pre></div><h2 id="branches" tabindex="-1">Branches <a class="header-anchor" href="#branches" aria-label="Permalink to &quot;Branches&quot;">​</a></h2><p>Changes on the default branch are the committed plan. Changes on other branches are provisional until they reach it, so a plan on a feature branch shows up in Wake without replacing what the default branch says.</p><h2 id="how-wake-reads-changes-and-tasks" tabindex="-1">How Wake reads changes and tasks <a class="header-anchor" href="#how-wake-reads-changes-and-tasks" aria-label="Permalink to &quot;How Wake reads changes and tasks&quot;">​</a></h2><p><code>wake sync</code> reads <code>openspec/changes/*/tasks.md</code> and <code>openspec/changes/archive/*/tasks.md</code>. Each change is a phase and each checkbox line a task; a checked box marks it done. Indented lines under a task describe it, and a <code>Done when:</code> line says how to tell it is finished:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">x</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] 1.1 Parse tokens &lt;!-- wake:k3q9x2mfa7 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ ] 1.2 Store tokens &lt;!-- wake:p2r8c4t6wz after:k3q9x2mfa7 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Tokens go to the session store, keyed by their hash.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  Done when: a stored token is found again after a restart.</span></span></code></pre></div><p>The task detail in the web app shows the description as Includes and the <code>Done when:</code> line as Done when; a task without them shows both empty. <code>/opsx:propose</code> may write bare checkbox lines, so the <code>wake-planning</code> skill has the agent add both to every task before <code>wake sync</code>. <code>wake sync</code> counts the open tasks without a <code>Done when:</code> line, and <code>wake doctor</code> lists them as <code>path:line</code>.</p><p>Tasks without an id get a trailing <code>&lt;!-- wake:&lt;id&gt; --&gt;</code> marker the first time Wake syncs them. Commit it: it keeps the task&#39;s identity through renames and moves. <code>after:</code> lists the tasks it depends on.</p><p>A malformed line is printed as <code>path:line: message</code>, and nothing is sent until it is fixed.</p>`,15)])])}const g=a(o,[["render",i]]);export{k as __pageData,g as default};
